#pragma once
#include <string.h>

// Right-trims trailing spaces from s IN PLACE.
// BUG (perf): strlen(s) is recomputed on every loop iteration, so trimming a
// string with k trailing spaces off a string of length n costs O(n*k) - for
// a long, mostly-trailing-space string this is effectively O(n^2).
static void rtrim_spaces(char *s) {
    while (strlen(s) > 0 && s[strlen(s) - 1] == ' ') {
        s[strlen(s) - 1] = '\0';
    }
}

