#include "rtrim.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

int main(void) {
    // A long string with a huge run of trailing spaces - the O(n*k) shape
    // is at its worst when trailing spaces dominate the string length.
    const int total_len = 700000;
    const int trailing = 685000;
    char *s = malloc(total_len + 1);
    for (int i = 0; i < total_len - trailing; i++) s[i] = 'x';
    for (int i = total_len - trailing; i < total_len; i++) s[i] = ' ';
    s[total_len] = '\0';

    clock_t start = clock();
    rtrim_spaces(s);
    clock_t end = clock();
    double elapsed_ms = 1000.0 * (double)(end - start) / CLOCKS_PER_SEC;

    int expected_len = total_len - trailing;
    int ok = (int)strlen(s) == expected_len;
    for (int i = 0; i < expected_len && ok; i++) {
        if (s[i] != 'x') ok = 0;
    }

    fprintf(stderr, "elapsed_ms=%.1f len=%d expected_len=%d\n", elapsed_ms, (int)strlen(s), expected_len);
    if (!ok) {
        printf("WRONG_OUTPUT\n");
        return 1;
    }
    if (elapsed_ms > 1000.0) {
        printf("TOO_SLOW %.1fms\n", elapsed_ms);
        return 1;
    }
    printf("PASS %.1fms\n", elapsed_ms);
    return 0;
}

