#pragma once
#include <string.h>

// Right-trims trailing spaces from s IN PLACE. O(n): strlen is computed
// once, then the trim walks backward from the cached end.
static void rtrim_spaces(char *s) {
    size_t len = strlen(s);
    while (len > 0 && s[len - 1] == ' ') {
        len--;
    }
    s[len] = '\0';
}

